// A cold boot or a short network outage gets a bounded chance to obtain fresh
// evidence. Confirmed absence never waits; missing configuration cannot recover itself.
inline bool waitForPresence(const Occurrence& occurrence, uint32_t now, Presence state, bool configured, bool firstCheckPending = false) {
  return configured && state == Presence::Unknown && (firstCheckPending || now < occurrence.start + PRESENCE_WAIT_SECONDS) &&
    now <= occurrence.wake + LATE_START_SECONDS;
}

// Calendar arithmetic is Gregorian (RFC 3339, section 5.7). These bounded loops
// are used for scheduling, never in the pixel pipeline.
inline bool leapYear(unsigned year) {
  return year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
}

inline unsigned monthDays(unsigned year, unsigned month) {
  static const uint8_t DAYS[] = {31,28,31,30,31,30,31,31,30,31,30,31};
  return month >= 1 && month <= 12 ? DAYS[month - 1] + (month == 2 && leapYear(year)) : 0;
}

inline bool validDate(uint32_t date) {
  const unsigned year = date / 10000, month = date / 100 % 100, day = date % 100;
  return year >= 2024 && year <= 2099 && day >= 1 && day <= monthDays(year, month);
}

// Convert a calendar date to a timezone-free midnight, represented as Unix seconds.
inline uint32_t dateEpoch(uint32_t date) {
  if (!validDate(date)) return 0;
  const unsigned year = date / 10000, month = date / 100 % 100;
  uint32_t days = date % 100 - 1;
  for (unsigned y = 1970; y < year; ++y) days += leapYear(y) ? 366 : 365;
  for (unsigned m = 1; m < month; ++m) days += monthDays(year, m);
  return days * SECONDS_PER_DAY;
}

inline uint32_t epochDate(uint32_t seconds) {
  uint32_t days = seconds / SECONDS_PER_DAY;
  unsigned year = 1970, month = 1;
  while (days >= (leapYear(year) ? 366U : 365U)) days -= leapYear(year++) ? 366 : 365;
  while (days >= monthDays(year, month)) days -= monthDays(year, month++);
  return year * 10000 + month * 100 + days + 1;
}

inline uint8_t mondayWeekday(uint32_t date) {
  return (dateEpoch(date) / SECONDS_PER_DAY + 3) % 7; // 1970-01-01 was Thursday.
}

struct Clock {
  uint32_t (*toLocal)(uint32_t);
  uint32_t (*toUtc)(uint32_t);
};

// Round-trip the WLED timezone conversion. Fall-back selects the first occurrence;
// a missing spring-forward time is moved forward by the one-hour DST gap.
inline uint32_t resolveLocal(uint32_t local, const Clock& clock) {
  uint32_t utc = clock.toUtc(local);
  if (clock.toLocal(utc) != local) {
    local += 3600;
    utc = clock.toUtc(local);
    if (clock.toLocal(utc) != local) return 0;
  }
  if (utc >= 3600 && clock.toLocal(utc - 3600) == local) utc -= 3600;
  return utc;
}

inline bool occursOn(const Alarm& alarm, uint32_t date) {
  if (!alarm.enabled || date <= alarm.lastDate || date == alarm.skipDate) return false;
  return alarm.weekdays ? (alarm.weekdays & (1U << mondayWeekday(date))) != 0 : date == alarm.date;
}

inline Occurrence occurrenceOn(const Alarm& alarm, uint8_t index, uint32_t date, const Clock& clock) {
  Occurrence result;
  if (!validDate(date) || !occursOn(alarm, date)) return result;
  result.wake = resolveLocal(dateEpoch(date) + alarm.wakeMinute * 60U, clock);
  if (!result.wake) return result;
  result.index = index;
  result.date = date;
  result.start = result.wake - alarm.rampMinutes * 60U;
  result.end = result.wake + (alarm.holdMinutes + alarm.fadeMinutes) * 60U;
  return result;
}

// Search yesterday through the next week, so a Monday alarm may begin on Sunday.
// Due alarms use a bounded catch-up window; old alarms are not replayed hours later.
inline Occurrence nextOccurrence(const Config& config, uint32_t now, const Clock& clock, bool dueOnly = false) {
  Occurrence best;
  if (!config.enabled) return best;
  const uint32_t midnight = clock.toLocal(now) / SECONDS_PER_DAY * SECONDS_PER_DAY;
  for (int dayOffset = -1; dayOffset <= 8; ++dayOffset) {
    const uint32_t date = epochDate(midnight + dayOffset * int32_t(SECONDS_PER_DAY));
    for (uint8_t i = 0; i < config.count; ++i) {
      Occurrence candidate = occurrenceOn(config.alarms[i], i, date, clock);
      if (!candidate || now > candidate.wake + LATE_START_SECONDS || now >= candidate.end) continue;
      if (dueOnly && candidate.start > now) continue;
      if (!best || candidate.start < best.start ||
          (candidate.start == best.start && strcmp(config.alarms[i].id, config.alarms[best.index].id) < 0)) best = candidate;
    }
  }
  return best;
}

struct Frame {
  Phase phase = Phase::Idle;
  uint8_t brightness = 0;
  uint8_t blend = 0;
  uint8_t progress = 0;
};

// A fixed-point smoothstep avoids a sudden start and end to the brightness ramp.
// Reference: https://en.wikipedia.org/wiki/Smoothstep (cubic Hermite interpolation).
inline uint16_t smoothProgress(uint32_t elapsed, uint32_t duration) {
  if (!duration || elapsed >= duration) return 65535;
  const uint64_t p = uint64_t(elapsed) * 65535 / duration;
  return p * p * (196605 - 2 * p) / (uint64_t(65535) * 65535);
}

class Runner {
  Alarm _alarm;
  uint32_t _since = 0, _offset = 0;
  uint32_t _rise = 0, _hold = 0, _fade = 0;
  uint32_t _snoozeSince = 0, _snoozeFor = 0;
  uint32_t _started = 0;
  bool _active = false, _preview = false, _snoozed = false, _forcedFade = false;
  uint8_t _fadeFrom = 0, _fadeBlend = 255;

public:
  bool active() const { return _active; }
  bool preview() const { return _preview; }
  const Alarm& alarm() const { return _alarm; }

  // All phase durations use monotonic time: an NTP correction cannot restart a ramp.
  void start(const Alarm& alarm, uint32_t nowMs, uint32_t initialElapsed = 0, bool preview = false) {
    _alarm = alarm;
    _since = _started = nowMs;
    _offset = initialElapsed;
    _preview = preview;
    _rise = preview ? 20000 : alarm.rampMinutes * 60000U;
    _hold = preview ? 5000 : alarm.holdMinutes * 60000U;
    _fade = preview ? 5000 : alarm.fadeMinutes * 60000U;
    _active = true;
    _snoozed = _forcedFade = false;
  }

  void stop() { _active = _snoozed = false; }

  // Snooze is dark, then uses a one-minute ramp. Repeated snoozes cannot run forever.
  bool snooze(uint32_t nowMs) {
    if (!_active || _preview || _forcedFade || nowMs - _started > 6U * 3600000U) return false;
    _snoozed = true;
    _snoozeSince = nowMs;
    _snoozeFor = _alarm.snoozeMinutes * 60000U;
    return true;
  }

  void fadeOut(uint32_t nowMs, const Frame& current) {
    if (!_active || _forcedFade) return;
    _forcedFade = true;
    _snoozed = false;
    _since = nowMs;
    _offset = 0;
    _fade = 3000;
    _fadeFrom = current.brightness;
    _fadeBlend = current.blend;
  }

  Frame frame(uint32_t nowMs) {
    Frame output;
    if (!_active) return output;
    if (nowMs - _started >= 7U * 3600000U) { stop(); output.phase = Phase::Finished; return output; }
    if (_snoozed) {
      if (nowMs - _snoozeSince < _snoozeFor) { output.phase = Phase::Snoozed; return output; }
      _snoozed = false;
      _since = nowMs;
      _offset = 0;
      _rise = 60000;
    }
    const uint32_t elapsed = nowMs - _since + _offset;
    if (_forcedFade) {
      output.phase = Phase::Fading;
      output.blend = _fadeBlend;
      output.brightness = uint32_t(_fadeFrom) * (65535 - smoothProgress(elapsed, _fade)) / 65535;
      if (elapsed >= _fade) { stop(); output.phase = Phase::Finished; }
      return output;
    }
    output.progress = uint64_t(elapsed < _rise ? elapsed : _rise) * 100 / (_rise ? _rise : 1);
    if (!_rise) output.progress = 100;
    if (elapsed < _rise) {
      output.phase = Phase::Rising;
      const uint16_t progress = smoothProgress(elapsed, _rise);
      output.blend = progress >> 8;
      output.brightness = uint32_t(_alarm.brightness) * progress / 65535;
    } else if (elapsed < _rise + _hold) {
      output.phase = Phase::Holding;
      output.blend = 255;
      output.brightness = _alarm.brightness;
    } else if (_fade && elapsed < _rise + _hold + _fade) {
      output.phase = Phase::Fading;
      output.blend = 255;
      output.brightness = uint32_t(_alarm.brightness) * (65535 - smoothProgress(elapsed - _rise - _hold, _fade)) / 65535;
    } else {
      stop();
      output.phase = Phase::Finished;
    }
    return output;
  }
};

class PresenceTracker {
  Presence _lastSample = Presence::Unknown;
  uint32_t _lastPositive = 0, _lastObservation = 0;
  bool _seenPositive = false, _seenObservation = false;
  bool _positiveExpired = false, _observationExpired = false;

public:
  static constexpr uint32_t MAX_AGE_MS = 60U * 60000U;
  static constexpr uint32_t OBSERVATION_AGE_MS = 15U * 60000U;
  void reset() { _lastSample = Presence::Unknown; _seenPositive = _seenObservation = _positiveExpired = _observationExpired = false; }

  // Latch expiry during idle periods, so a 49-day millis() rollover can never
  // make a long-expired confirmation appear fresh again when monitoring resumes.
  void expire(uint32_t nowMs) {
    if (_seenPositive && nowMs - _lastPositive >= MAX_AGE_MS) _positiveExpired = true;
    if (_seenObservation && nowMs - _lastObservation >= OBSERVATION_AGE_MS) _observationExpired = true;
  }

  // A failed round never shortens the 60-minute confirmation lease. Network
  // errors do not establish absence, and cannot refresh the last real response.
  void observe(Presence sample, uint32_t nowMs) {
    _lastSample = sample;
    if (sample == Presence::Present) {
      _lastPositive = nowMs;
      _seenPositive = true;
      _positiveExpired = false;
    }
    _lastObservation = nowMs;
    _seenObservation = true;
    _observationExpired = false;
  }

  Presence state(uint32_t nowMs) const {
    if (_seenPositive && !_positiveExpired && nowMs - _lastPositive < MAX_AGE_MS) return Presence::Present;
    return _seenObservation && !_observationExpired && _lastSample == Presence::Absent && nowMs - _lastObservation < OBSERVATION_AGE_MS ? Presence::Absent : Presence::Unknown;
  }
  uint32_t age(uint32_t nowMs) const { return _seenObservation ? nowMs - _lastObservation : UINT32_MAX; }
  uint32_t confirmationAge(uint32_t nowMs) const {
    const uint32_t age = nowMs - _lastPositive;
    return _seenPositive && !(_positiveExpired && age < MAX_AGE_MS) ? age : UINT32_MAX;
  }
  uint32_t remaining(uint32_t nowMs) const {
    const uint32_t elapsed = confirmationAge(nowMs);
    return !_positiveExpired && elapsed < MAX_AGE_MS ? MAX_AGE_MS - elapsed : 0;
  }
  bool grace(uint32_t nowMs) const { return remaining(nowMs) && (_lastSample != Presence::Present || confirmationAge(nowMs) > 60000); }
};

enum class Monitoring : uint8_t { Paused, Scheduled, BeforeAlarm, Running };

struct PresencePolicy {
  Monitoring mode = Monitoring::Paused;
  uint32_t intervalMs = 0;
};

// All windows refer to light start, not wake time. Rendering/snooze use a
// monotonic runner, so monitoring an active alarm does not depend on wall-clock validity.
inline PresencePolicy presencePolicy(bool enabled, bool validClock, const Occurrence& next, bool running, uint32_t now) {
  PresencePolicy policy;
  if (!enabled) return policy;
  if (running) { policy.mode = Monitoring::Running; policy.intervalMs = 10U * 60000U; }
  else if (validClock && next && next.start <= now + 90U * 60U) {
    policy.mode = next.start <= now + 30U * 60U ? Monitoring::BeforeAlarm : Monitoring::Scheduled;
    policy.intervalMs = (policy.mode == Monitoring::BeforeAlarm ? 5U : 15U) * 60000U;
  }
  return policy;
}

class PresenceTiming {
  uint32_t _lastCheck = 0;
  bool _checked = false;
public:
  void reset() { _checked = false; }
  void completed(uint32_t nowMs) { _lastCheck = nowMs; _checked = true; }
  uint32_t age(uint32_t nowMs) const { return _checked ? nowMs - _lastCheck : UINT32_MAX; }
  // Manual commands are coalesced/rate-limited, not an unrestricted fast polling mode.
  uint32_t until(uint32_t nowMs, uint32_t interval, bool requested) const {
    if (!requested && !interval) return UINT32_MAX;
    if (!_checked) return 0;
    const uint32_t wait = requested ? 5000 : interval;
    return nowMs - _lastCheck < wait ? wait - (nowMs - _lastCheck) : 0;
  }
};

class PresenceBurst {
  uint8_t _attempts = 1; // The first UDP question is sent when the round starts.
  uint32_t _lastAttempt = 0;
public:
  static constexpr uint8_t MAX_ATTEMPTS = 8;
  static constexpr uint32_t TIMEOUT_MS = 75000;
  static constexpr uint32_t RECEIVE_WINDOW_MS = TIMEOUT_MS + 5000;
  void reset() { _attempts = 1; _lastAttempt = 0; }
  uint8_t attempts() const { return _attempts; }
  bool due(uint32_t elapsed) const {
    static const uint32_t OFFSETS[MAX_ATTEMPTS] = {0, 5000, 12000, 22000, 30000, 40000, 50000, 60000};
    return _attempts < MAX_ATTEMPTS && elapsed >= OFFSETS[_attempts] && elapsed - _lastAttempt >= 5000;
  }
  void advanced(uint32_t elapsed) { if (_attempts < MAX_ATTEMPTS) ++_attempts; _lastAttempt = elapsed; }
  bool fallbackDue(uint32_t elapsed) const { return _attempts >= MAX_ATTEMPTS && elapsed - _lastAttempt >= 5000; }
};

